import { nativeRequest } from './native-console.js';
import { discoveryCheck,discoveryConfigReady,discoveryContext,discoveryRequest,checkedDiscoveryPage,discoveryCoverageText,discoveryCopy,discoveryFreeze,discoveryFetch,discoveryId } from './discovery-contract.js';

const json=v=>JSON.stringify(v,null,2),sum=v=>v.reduce((a,b)=>a+BigInt(b),0n),key=r=>r.instanceHex&&r.type==='ROOT'?r.instanceHex:r.positionIdHex??r.sourceIdHex??r.address;
const classes=['AA','NUC','LIPID','SUGAR'];
const formatLab=v=>`${v/1000000n}.${String(v%1000000n).padStart(6,'0')}`;
function selected(page,value,config){const context=discoveryContext(config);discoveryCheck(page?.query.actor===config.sessionActor&&page.result.decision==='DISCOVERY_PAGE'&&Object.entries(context).every(([k,v])=>page.result.context[k]===v),'请先读取当前账户的实际发现页。');const row=page.result.rows.find(r=>key(r)===value);discoveryCheck(row,'请选择本页实际核验的记录。');return row;}
const selectionKey=(entry,section)=>section==='roots'?entry.instanceHex:entry.sourceIdHex;
function checkedSelection(selection,config){
  const context=discoveryContext(config);discoveryCheck(selection&&Object.keys(selection).sort().join(',')==='actor,context,entries,query,section'&&selection.actor===config.sessionActor&&selection.query===''&&['roots','sources'].includes(selection.section),'待选集不属于当前账户或分类。');
  discoveryCheck(selection.context&&Object.keys(selection.context).length===4&&Object.entries(context).every(([k,v])=>selection.context[k]===v),'待选集不属于当前发布。');const root=selection.section==='roots';discoveryCheck(Array.isArray(selection.entries)&&selection.entries.length<=(root?6:16),'待选集超出数量上限。');const ids=new Set(),projects=new Set();
  for(const entry of selection.entries){discoveryCheck(entry&&Object.keys(entry).sort().join(',')===(root?'instanceHex':'projectIdHex,sourceIdHex'),'待选集只允许保存 ID。');const id=discoveryId(selectionKey(entry,selection.section));discoveryCheck(!ids.has(id),'待选集包含重复 ID。');ids.add(id);if(!root)projects.add(discoveryId(entry.projectIdHex));}discoveryCheck(projects.size<=8,'Source 待选集最多涉及 8 个项目。');return selection;
}
export function createDiscoverySelection(config,section){discoveryCheck(['roots','sources'].includes(section),'此分类不支持待选集。');return discoveryFreeze({actor:config.sessionActor,context:discoveryContext(config),section,query:'',entries:[]});}
export function addDiscoverySelection(selection,page,value,config){
  checkedSelection(selection,config);discoveryCheck(page?.query.section===selection.section&&page.query.query==='','待选集与当前发现查询不一致。');const row=selected(page,value,config),root=selection.section==='roots';
  discoveryCheck(root?row.type==='ROOT'&&row.lifecycle==='LIVE'&&row.owner===config.sessionActor:row.type==='SOURCE'&&row.owner===config.sessionActor&&sum(row.remainingTick)>0n,'只能加入本页已核验的 LIVE 成品或有剩余物种的 Source。');
  const entry=root?{instanceHex:row.instanceHex}:{sourceIdHex:row.sourceIdHex,projectIdHex:row.projectIdHex},id=selectionKey(entry,selection.section),previous=selection.entries.find(e=>selectionKey(e,selection.section)===id);if(previous){discoveryCheck(root||previous.projectIdHex===entry.projectIdHex,'同一 Source 的项目绑定出现矛盾，请重新扫描。');return selection;}
  const next={...selection,entries:[...selection.entries,entry]};checkedSelection(next,config);return discoveryFreeze(next);
}
export function removeDiscoverySelection(selection,value,config){checkedSelection(selection,config);discoveryCheck(selection.entries.some(e=>selectionKey(e,selection.section)===value),'请选择待选集中实际存在的 ID。');return discoveryFreeze({...selection,entries:selection.entries.filter(e=>selectionKey(e,selection.section)!==value)});}
export function handoffDiscoverySelection(document,selection,config){
  checkedSelection(selection,config);discoveryCheck(selection.entries.length>0,'待选集为空。');const root=selection.section==='roots',view=root?'synthesis':'manufacture',tab=root?'synthesis-tab-plan':'manufacture-tab-plan',fields=root?{'synthesis-actor':config.sessionActor,'synthesis-direct':selection.entries.map(e=>e.instanceHex).join('\n')}:{'manufacture-actor':config.sessionActor,'manufacture-projects':[...new Set(selection.entries.map(e=>e.projectIdHex))].sort().join('\n'),'manufacture-sources':selection.entries.map(e=>e.sourceIdHex).join('\n')};
  const nav=[...document.querySelectorAll('.nav-item')].find(b=>b.dataset.view===view),panel=document.getElementById(tab),elements=Object.entries(fields).map(([id,text])=>({el:document.getElementById(id),text}));discoveryCheck(nav&&panel&&elements.every(e=>e.el),'现有严格读取页面不可用。');const EventClass=document.defaultView?.Event??globalThis.Event;for(const {el,text}of elements){el.value=text;el.dispatchEvent(new EventClass('input',{bubbles:true}));}panel.click();nav.click();
}

/** Fields and navigation only. Existing strict readers must run explicitly. */
export function handoffDiscoveredWalletRow(document,page,value,config,destination){
  const row=selected(page,value,config),actor=config.sessionActor;let fields,view,tab=null;
  if(destination==='asset'||destination==='mining'){
    discoveryCheck(row.type==='ROOT'||row.type==='POSITION','只有实际作品或历史Position可进入权益读取。');const instance=row.instanceHex,start=row.type==='POSITION'?row.positionSeq:'0';
    if(destination==='asset'){view='guided';tab='guided-tab-asset';fields={'guided-actor':actor,'guided-instance':instance,'guided-page-start':start,'guided-page-limit':row.type==='POSITION'?'1':'5'};}
    else{view='mining';tab='mining-tab-dashboard';fields={'mining-actor':actor,'mining-instances':instance,'mining-page-start':start,'mining-page-limit':row.type==='POSITION'?'1':'5'};}
  }else if(destination==='synthesis'){
    discoveryCheck(row.type==='ROOT'&&row.lifecycle==='LIVE'&&row.owner===actor,'合成输入必须是当前账户的 LIVE 成品。');view='synthesis';tab='synthesis-tab-plan';fields={'synthesis-actor':actor,'synthesis-direct':row.instanceHex};
  }else{
    discoveryCheck(destination==='inventory'&&(row.type==='SOURCE'||row.type==='MATERIAL_ATA'),'代币提示不能直接进入制造库存。');if(row.type==='SOURCE')discoveryCheck(sum(row.remainingTick)>0n,'此 Source 已无剩余物种预算。');view='manufacture';tab='manufacture-tab-plan';fields={'manufacture-actor':actor,'manufacture-projects':row.projectIdHex,'manufacture-sources':row.type==='SOURCE'?row.sourceIdHex:''};
  }
  const nav=[...document.querySelectorAll('.nav-item')].find(b=>b.dataset.view===view);discoveryCheck(nav,'现有严格读取页面不可用。');const EventClass=document.defaultView?.Event??globalThis.Event;
  for(const [name,text]of Object.entries(fields)){const el=document.getElementById(name);discoveryCheck(el,'现有读取表单不可用。');el.value=text;el.dispatchEvent(new EventClass('input',{bubbles:true}));}if(tab){const el=document.getElementById(tab);discoveryCheck(el,'现有读取面板不可用。');el.click();}nav.click();
}

function rowTitle(row){if(row.type==='ROOT')return row.target===null?'当前功能部件':row.target===22?'当前生物':row.target<=15?`当前细胞 C${String(row.target).padStart(2,'0')}`:`当前器官 O${String(row.target-15).padStart(2,'0')}`;if(row.type==='POSITION')return `历史权益 #${row.positionSeq}`;if(row.type==='SOURCE')return `${classes[row.class-1]} · Source 剩余物种预算`;if(row.type==='MATERIAL_ATA')return `${classes[row.class-1]} · 实际原料 ATA`;return row.protocolMatch==='LAB'?'LAB 代币余额提示':'待识别 classic 代币提示';}
function details(row){
  if(row.type==='ROOT')return [['实例 ID',row.instanceHex],['当前所有人',row.owner],['生命周期',row.lifecycle],['品质 ppm',row.qualityPpm],['B / retired',`${row.B} / ${row.retired}`],['revision',row.revision],['登记普通Position数',row.registration.ordinaryCount],['资格','仅实际记录，不代表当前可质押或可消费']];
  if(row.type==='POSITION')return [['Position ID',row.positionIdHex],['作品 ID',row.instanceHex],['固定受益人',row.beneficiary],['当前作品所有人',row.rootOwner],['当前作品生命周期',row.rootLifecycle],['开始 / 结束小时',`${row.start} / ${row.end??'未结束'}`],['已计债 / 已领取 LAB 原子',`${row.accrued} / ${row.paid}`],['本段已计债未领 LAB 原子',String(BigInt(row.accrued)-BigInt(row.paid))],['下个待结小时',row.nextUnsettledHour]];
  if(row.type==='SOURCE')return [['Source ID',row.sourceIdHex],['项目 ID',row.projectIdHex],['原始摄入标准份数（历史）',row.unitCount],['剩余物种 ticks 总和（非标准份数）',String(sum(row.remainingTick))],['已消费物种 ticks 总和',String(sum(row.spentPrefix))],['说明','原始摄入不能加回当前原料余额；剩余能否制造须重读并核对BOM']];
  if(row.type==='MATERIAL_ATA')return [['项目 ID',row.projectIdHex],['mint',row.mint],['ATA',row.address],['当前标准单位 / 份',row.amount],['制造状态','尚未纳入制造库存，需现有 inventory-read 重读']];
  return [['代币账户',row.address],['mint',row.mint],['原始 token amount',row.amount],['标准 ATA',row.isStandardAta?'是':'否'],['协议识别',row.protocolMatch==='LAB'?'固定 LAB mint 提示':'UNRESOLVED · 未识别，不表示非协议资产'],['边界','不含 Token2022 / NFT；未纳入制造，不能直接支出或领取']];
}

export async function mountWalletDiscovery(document,{fetchImpl=globalThis.fetch}={}){
  const $=id=>document.getElementById(id);if(!$('wallet-discovery-view'))return;const state={config:null,generation:0,page:null,selection:'',resume:null,basket:null,picked:''};let active=null,configController=null,busy=false,configBusy=false;
  const fetchRead=discoveryFetch(fetchImpl,()=>{state.config=null;configController?.abort();configController=null;configBusy=false;invalidate('登录或访问权限已失效；请刷新会话并重读配置。');$('wallet-discovery-config-badge').textContent='权限失效 · 发现关闭';});
  const message=(text,error=false)=>{$('wallet-discovery-message').textContent=text;$('wallet-discovery-message').className=`native-message${error?' error':''}`;};
  function invalidate(text='分类或身份变化；旧页、继续标识与交接已清除。'){active?.abort();active=null;busy=false;state.generation++;state.page=null;state.selection='';state.resume=null;state.basket=null;state.picked='';message(text);render();}
  function render(){
    const ready=discoveryConfigReady(state.config),page=state.page?.result,row=page?.rows.find(r=>key(r)===state.selection),usable=ready&&!busy&&!configBusy&&page?.decision==='DISCOVERY_PAGE'&&!!row;
    $('wallet-discovery-actor').textContent=ready?state.config.sessionActor:'未登录当前发布';$('wallet-discovery-section').disabled=!ready||busy||configBusy;$('wallet-discovery-start').disabled=!ready||busy||configBusy;$('wallet-discovery-next').disabled=!ready||busy||configBusy||!(page?.nextCursor??state.resume?.cursor)||page?.decision==='DISCOVERY_RESTART_REQUIRED';$('wallet-discovery-next').textContent=state.resume?'重试本次继续请求':'继续有界扫描';$('wallet-discovery-reset').disabled=busy||configBusy||!page&&!state.resume;$('wallet-discovery-selection').disabled=!ready||busy||configBusy||page?.decision!=='DISCOVERY_PAGE'||!page.rows.length;
    for(const destination of ['asset','mining'])$('wallet-discovery-'+destination).disabled=!usable||!['ROOT','POSITION'].includes(row.type);$('wallet-discovery-synthesis').disabled=!usable||row.type!=='ROOT';$('wallet-discovery-inventory').disabled=!usable||!['SOURCE','MATERIAL_ATA'].includes(row.type)||row.type==='SOURCE'&&sum(row.remainingTick)===0n;
    const section=$('wallet-discovery-section').value,basketAllowed=['roots','sources'].includes(section),entries=state.basket?.entries??[];let basketCurrent=false;try{basketCurrent=!!state.basket&&checkedSelection(state.basket,state.config).section===section;}catch{}
    $('wallet-discovery-basket-panel').hidden=!basketAllowed;$('wallet-discovery-add').disabled=!usable||!basketAllowed||page?.section!==section||row.type==='SOURCE'&&sum(row.remainingTick)===0n;$('wallet-discovery-clear-picked').disabled=!ready||busy||configBusy||!entries.length;$('wallet-discovery-use-picked').disabled=!ready||busy||configBusy||!basketCurrent||!entries.length;$('wallet-discovery-remove-picked').disabled=!ready||busy||configBusy||!basketCurrent||!entries.some(e=>selectionKey(e,section)===state.picked);$('wallet-discovery-picked').disabled=!ready||busy||configBusy||!entries.length;
    $('wallet-discovery-add').textContent=section==='roots'?'将当前成品 ID 加入合成待选':'将当前 Source ID 加入待选';$('wallet-discovery-use-picked').textContent=section==='roots'?'将已选 ID 填入合成输入':'将已选 ID 填入制造库存读取';$('wallet-discovery-picked-count').textContent=section==='roots'?`已选 ${entries.length} / 6 个成品 ID · 未验证合成层级或可用性`:`已选 ${entries.length} / 16 个 Source ID · 涉及 ${new Set(entries.map(e=>e.projectIdHex)).size} / 8 个项目`;
    $('wallet-discovery-picked').replaceChildren();const none=document.createElement('option');none.value='';none.textContent='选择待移除的已选 ID';$('wallet-discovery-picked').append(none);for(const entry of entries){const o=document.createElement('option');o.value=selectionKey(entry,section);o.textContent=section==='roots'?entry.instanceHex:`${entry.sourceIdHex} · 项目 ${entry.projectIdHex}`;$('wallet-discovery-picked').append(o);}$('wallet-discovery-picked').value=state.picked;
    $('wallet-discovery-coverage').textContent=page?discoveryCoverageText(page.coverage):'尚未读取；每个分类有独立覆盖，不代表整个钱包。';$('wallet-discovery-json').textContent=page?json(page):'尚未读取';$('wallet-discovery-count').textContent=page?`本页 ${page.rows.length} 条已核验记录`:'每页最多 8 条实际记录';
    $('wallet-discovery-total').textContent=page?(page.section==='positions'?`本页固定受益Position已计债未领 ${sum(page.rows.map(r=>String(BigInt(r.accrued)-BigInt(r.paid))))} LAB 原子；不含未结小时，不是钱包余额，也不另加K奖励。`:page.section==='token-owner-hints'?`本页 LAB 提示余额 ${formatLab(sum(page.rows.filter(r=>r.protocolMatch==='LAB').map(r=>r.amount)))} LAB；只覆盖本页已核验提示，不保证当前可支出。`:page.section==='sources'?'Source 原始摄入仅作历史记录；可用剩余看 remainingTick，不得把原始摄入份数加回余额。':page.section==='roots'?'只列此账户当前 LIVE 成品；被消费的祖先不再列为可用作品。':'只列实际正余额的原料 ATA；已摄入 Source 与可用 token 单位分别核对。'):'各类金额分别核对，不将未领权益、历史摄入或提示余额合并成可支出总额。';
    $('wallet-discovery-rows').replaceChildren();$('wallet-discovery-selection').replaceChildren();const placeholder=document.createElement('option');placeholder.value='';placeholder.textContent='明确选择本页记录';$('wallet-discovery-selection').append(placeholder);
    for(const record of page?.rows??[]){const opt=document.createElement('option');opt.value=key(record);opt.textContent=`${rowTitle(record)} · ${key(record)}`;$('wallet-discovery-selection').append(opt);const card=document.createElement('article');card.className='discovery-row';const h=document.createElement('h3');h.textContent=rowTitle(record);const dl=document.createElement('dl');dl.className='native-summary';for(const [label,value]of details(record)){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;dl.append(dt,dd);}const observed=document.createElement('p');observed.className='native-hint';observed.textContent=`实际记录观察 slot ${record.observedSlot}`;card.append(h,dl,observed);$('wallet-discovery-rows').append(card);}
    if(page&&!page.rows.length){const p=document.createElement('p');p.className='native-hint';p.textContent=page.coverage.pending?'本页无返回记录，仍有待处理工作；可继续当前分类扫描。':'本次遍历没有返回记录；请结合覆盖限制判断，不能据此声明整个钱包为空。';$('wallet-discovery-rows').append(p);}$('wallet-discovery-selection').value=state.selection;
  }
  async function loadConfig(){configController?.abort();const c=new AbortController();configController=c;configBusy=true;state.config=null;invalidate('正在读取固定发布与登录账户；不会连接钱包。');$('wallet-discovery-config-badge').textContent='读取中';try{const r=await nativeRequest('config',undefined,{fetchImpl:fetchRead,signal:c.signal});if(configController!==c)return;state.config=discoveryFreeze(discoveryCopy(r));$('wallet-discovery-config-badge').textContent=discoveryConfigReady(r)?'已登录 · 只读发现':'需要登录 · 发现关闭';message(discoveryConfigReady(r)?'明确选择一个分类开始扫描；后续操作仍需已有严格reader重读。':'先登录当前发布；钱包发现与全部交接保持关闭。');}catch(e){if(configController===c){$('wallet-discovery-config-badge').textContent='配置不可用 · 已关闭';message(e.message,true);}}finally{if(configController===c){configController=null;configBusy=false;render();}}}
  async function readPage(next){
    if(busy||configBusy||!discoveryConfigReady(state.config))return;let query;try{query=discoveryRequest({config:state.config,section:$('wallet-discovery-section').value,cursor:next?(state.page?.result.nextCursor??state.resume?.cursor):null,query:''});if(next)discoveryCheck(query.cursor!==null,'没有可继续的当前扫描。');}catch(e){message(e.message,true);return;}
    active?.abort();const c=new AbortController(),generation=++state.generation,config=state.config;active=c;busy=true;state.page=null;state.selection='';state.resume=null;if(!next){state.basket=null;state.picked='';}message('正在读取当前分类实际记录；不调用钱包、不产生交易。');render();
    try{const r=await nativeRequest('discovery-read',query,{fetchImpl:fetchRead,signal:c.signal});if(active!==c||state.generation!==generation||state.config!==config)return;state.page=checkedDiscoveryPage(r,query,config);message(r.decision==='DISCOVERY_RESTART_REQUIRED'?'扫描标识过期或已失效，请从头重扫。':r.decision==='DISCOVERY_BLOCKED'?'本分类发现受阻；不等同于零资产。':'已核验本页记录；交接只填入旧页面，必须明确重读。');}catch(e){if(active===c&&state.generation===generation){if(query.cursor!==null)state.resume=discoveryFreeze(discoveryCopy(query));message(e.message,true);}}finally{if(active===c&&state.generation===generation){active=null;busy=false;render();}}
  }
  for(const event of ['input','change'])$('wallet-discovery-section').addEventListener(event,()=>invalidate());$('wallet-discovery-selection').addEventListener('change',()=>{state.selection=$('wallet-discovery-selection').value;render();});$('wallet-discovery-start').addEventListener('click',()=>void readPage(false));$('wallet-discovery-next').addEventListener('click',()=>void readPage(true));$('wallet-discovery-reset').addEventListener('click',()=>invalidate('扫描已清除；请明确开始新的分类读取。'));$('wallet-discovery-reload').addEventListener('click',()=>void loadConfig());
  for(const destination of ['asset','mining','synthesis','inventory'])$('wallet-discovery-'+destination).addEventListener('click',()=>{if(!busy&&discoveryConfigReady(state.config))try{handoffDiscoveredWalletRow(document,state.page,state.selection,state.config,destination);}catch(e){message(e.message,true);}});
  $('wallet-discovery-add').addEventListener('click',()=>{if(!busy&&!configBusy&&discoveryConfigReady(state.config))try{const section=$('wallet-discovery-section').value;discoveryCheck(state.page?.query.section===section,'请重读当前分类。');const basket=state.basket??createDiscoverySelection(state.config,section),next=addDiscoverySelection(basket,state.page,state.selection,state.config),duplicate=next===basket;state.basket=next;message(duplicate?'此 ID 已在待选集，不重复加入。':'已加入待选 ID；不累计原始摄入或预算金额，交接后必须严格重读。');render();}catch(e){message(e.message,true);}});
  $('wallet-discovery-picked').addEventListener('change',()=>{state.picked=$('wallet-discovery-picked').value;render();});$('wallet-discovery-remove-picked').addEventListener('click',()=>{if(!busy&&discoveryConfigReady(state.config))try{state.basket=removeDiscoverySelection(state.basket,state.picked,state.config);state.picked='';message('已移除所选 ID；没有资产或预算变化。');render();}catch(e){message(e.message,true);}});$('wallet-discovery-clear-picked').addEventListener('click',()=>{if(!busy){state.basket=null;state.picked='';message('已清空待选 ID，当前发现页和游标保留。');render();}});
  $('wallet-discovery-use-picked').addEventListener('click',()=>{if(!busy&&!configBusy&&discoveryConfigReady(state.config))try{discoveryCheck(state.basket?.section===$('wallet-discovery-section').value,'待选分类已变化。');handoffDiscoverySelection(document,state.basket,state.config);}catch(e){message(e.message,true);}});
  document.querySelectorAll('.nav-item').forEach(button=>button.addEventListener('click',()=>{invalidate('视图已切换；旧发现记录与交接已失效。');document.querySelectorAll('.view').forEach(view=>{view.hidden=view.id!==`${button.dataset.view}-view`;});if(button.dataset.view==='wallet-discovery')$('page-title').textContent='我的 BioLab 资产';if(button.dataset.view==='directory')$('page-title').textContent='实验室发售目录';}));document.addEventListener?.('biolab-auth-change',()=>{state.config=null;invalidate('登录身份变化；分类记录与继续标识已清除。');void loadConfig();});await loadConfig();return {state,render};
}
if(typeof document!=='undefined')void mountWalletDiscovery(document).catch(()=>{const el=document.getElementById('wallet-discovery-message');if(el)el.textContent='钱包发现不可用；读取与交接保持关闭。';});
